"use strict";
(function () {
  const state = { tab: "visitors", visitors: "week", bots: "week" };
  function load() {
    if (document.hidden) return;
    const url = state.tab === "setup" ? "/admin/analytics/fragments/setup" :
      "/admin/analytics/fragments/" + (state.tab === "bots" ? "bot-stats" : "stats") + "?period=" + state[state.tab];
    return talkDOM.send("content get: " + url + " apply: inner").catch(function () {
      // Keep the last successful report visible.
    });
  }
  window.switchTab = function (tab) {
    state.tab = tab;
    document.querySelectorAll(".tab-btn").forEach(el => el.classList.toggle("active", el.dataset.tab === tab));
    const selector = document.getElementById("period-selector");
    if (selector) selector.style.display = tab === "setup" ? "none" : "flex";
    document.querySelectorAll(".period-btn").forEach(el => el.classList.toggle("active", el.dataset.period === state[tab]));
    load();
  };
  window.loadPeriod = function (period) {
    state[state.tab] = period;
    document.querySelectorAll(".period-btn").forEach(el => el.classList.toggle("active", el.dataset.period === period));
    load();
  };
  setInterval(function () { if (state.tab !== "setup") load(); }, 60000);
  document.addEventListener("visibilitychange", function () { if (!document.hidden) load(); });
  load();
})();
